import{M}from'./wind-packet-manifest.mjs';import{windPhase}from'./wind.mjs';
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
const abort=()=>Object.assign(Error('AJU_WIND_PACKET_STALE_OR_ABORTED'),{name:'AbortError'});
/** One scene-owned bank. Exactly current+next 8-phase packets, serial fetch/decode, no encoded cache. */
export function createAjuWindPackets({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b],{type:'image/png'})),signal}={}){
 let closed=false,generation=0,controller=null,pending=null,key=null,queue=Promise.resolve();const images=new Map;const stats={fetches:0,encodedBytes:0,decoded:0,closed:0,liveRGBABytes:0,peakRGBABytes:0,activeLoads:0,peakLoads:0};
 const phase=ms=>{if(!Number.isFinite(ms)||ms<0)throw Error('AJU_WIND_PACKET_TIME');return windPhase(ms)},live=g=>{if(closed||signal?.aborted||g!==generation)throw abort()};
 const close=im=>{stats.liveRGBABytes-=im.width*im.height*4;stats.closed++;im.close?.()},evict=k=>{const im=images.get(k);if(im){images.delete(k);close(im)}};
 const dispose=()=>{if(closed)return;closed=true;generation++;controller?.abort();pending=null;key=null;signal?.removeEventListener('abort',dispose);let first;for(const k of [...images.keys()])try{evict(k)}catch(e){first??=e}if(first)throw first};
 if(signal?.aborted)closed=true;else signal?.addEventListener('abort',dispose,{once:true});
 async function load(k,g,child){let image=null;const d=M.packets[k];stats.activeLoads++;stats.peakLoads=Math.max(stats.peakLoads,stats.activeLoads);try{live(g);const r=await fetcher(new URL(d.file,import.meta.url),{signal:child});if(!r.ok)throw Error('AJU_WIND_PACKET_HTTP');const raw=await r.arrayBuffer();let b=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw);live(g);stats.fetches++;stats.encodedBytes+=b.byteLength;if(b.byteLength!==d.bytes||await hash(b)!==d.sha256)throw Error('AJU_WIND_PACKET_PIN');live(g);image=await decode(b);b=null;stats.decoded++;stats.liveRGBABytes+=image.width*image.height*4;stats.peakRGBABytes=Math.max(stats.peakRGBABytes,stats.liveRGBABytes);live(g);if(image.width!==d.width||image.height!==d.height)throw Error('AJU_WIND_PACKET_DIMENSIONS');images.set(k,image);image=null;}finally{if(image)close(image);stats.activeLoads--;}}
 function request(ms){const p=phase(ms),block=Math.floor(p/8);if(closed||signal?.aborted)return Promise.reject(abort());if(pending&&key===block)return pending;if(!pending&&images.has(block)&&images.has((block+1)%8))return Promise.resolve();controller?.abort();controller=new AbortController();const child=controller.signal,g=++generation;key=block;const keep=[block,(block+1)%8];const job=queue.catch(()=>{}).then(async()=>{live(g);for(const k of [...images.keys()])if(!keep.includes(k))evict(k);for(const k of keep){live(g);if(!images.has(k))await load(k,g,child)}live(g)});queue=job;pending=job;job.then(()=>{if(g===generation)pending=null},()=>{if(g===generation)pending=null});return job}
 const ready=ms=>!closed&&!signal?.aborted&&images.has(Math.floor(phase(ms)/8));
 const imageFor=p=>{if(!Number.isInteger(p)||p<0||p>63)throw Error('AJU_WIND_PACKET_PHASE');const im=images.get(Math.floor(p/8));if(closed||signal?.aborted||!im)throw Error('AJU_WIND_PACKET_PENDING');return im};
 return Object.freeze({request,ready,drawBackground(g,region,p,x,y){const r=M.regions.indexOf(region);if(r<0)throw Error('AJU_WIND_PACKET_REGION');g.drawImage(imageFor(p),(p%8)*300,r*220,300,220,x,y,300,220)},drawSprite(g,variant,p,x,y){const v=M.variants.indexOf(variant);if(v<0)throw Error('AJU_WIND_PACKET_VARIANT');g.drawImage(imageFor(p),v*576+(p%8)*72,880,72,72,x,y,72,72)},stats:()=>Object.freeze({...stats,blocks:[...images.keys()],pending:!!pending,disposed:closed}),dispose});
}
